<?php
// Only called by local test fixtures; remove research generated by those fixtures.
function cleanupResearchFixtures(array $auditIds,array $userIds,array $cookieFiles): void {
    foreach($auditIds as $id){$q=db()->prepare('DELETE FROM usage_events WHERE audit_id=?');$q->execute([$id]);}
    foreach(array_filter($userIds) as $id){$q=db()->prepare('DELETE FROM usage_events WHERE user_id=?');$q->execute([$id]);}
    foreach($cookieFiles as $cookie){
        if(!$cookie||!is_file($cookie))continue;
        foreach(file($cookie) as $line){$parts=explode("\t",trim($line));if(count($parts)>=7&&$parts[5]==='audit_visitor'){$q=db()->prepare('DELETE FROM usage_events WHERE visitor_hash=?');$q->execute([hash('sha256',$parts[6])]);}}
    }
}
